-- ARC · Tortilla de patatas sin freír (patata troceada congelada de Mercadona)
insert into public.content_recipes (id, slot, mode, name, items, how, steps, plate, tupper, active, sort) values
  ('rl22', 'cena', 'sencilla', 'Tortilla de patatas sin freír', $arc$[["patataTroceada", "c"], ["claras", "p"], ["huevo", 120], ["cebolla", 60], ["aove", "f"]]$arc$::jsonb,
   'Tortilla jugosa con la patata troceada congelada de Mercadona hecha en la freidora de aire (sin freír), 2 huevos enteros y claras para subir la proteína.',
   $arc$["Echa la patata troceada directamente congelada en la freidora de aire con unas gotas de AOVE y sal: 8 minutos a 180 °C, remueve y otros 8 minutos. Sin freidora: cuécela 3 minutos en agua y escúrrela bien.", "Mientras, pocha la cebolla en la sartén antiadherente a fuego bajo con el resto del AOVE y una pizca de sal, hasta que esté blandita.", "Bate los 2 huevos con las claras y sal. Mezcla con la patata y la cebolla y déjalo reposar 5 minutos para que la patata se empape.", "Cuaja en una sartén pequeña antiadherente a fuego medio-bajo 4-5 minutos, dale la vuelta con un plato y 2-3 minutos más. Si te gusta jugosa, menos tiempo."]$arc$::jsonb, '', true, true, 121)
on conflict (id) do update set slot = excluded.slot, mode = excluded.mode, name = excluded.name, items = excluded.items, how = excluded.how, steps = excluded.steps, tupper = excluded.tupper, active = excluded.active;
